349	// local pack may not shadow a canon id — the collision is reported and the local
350	// one dropped (a consumer extends the canon, never silently overrides it).
351	export async function discoverPacks({ localRoot, session = false, checksFor = null } = {}) {
352	  const errors = [];
353	  const canon = await scanPackDir(packsDir, { local: false, checksFor }, errors);
354	  // Re-resolve each canon id now the whole tree is known, so an ABSORBED pack's
355	  // leftover directory keeps its own id instead of colliding with the survivor
356	  // sitting beside it (#1186). scanPackDir cannot make this call alone: it sees
357	  // one directory at a time, and the map reads the same for a rename.
358	  const rawCanonIds = new Set(canon.map((p) => p.rawId));
359	  for (const pack of canon) pack.id = canonicalPackIdAmong(pack.rawId, rawCanonIds);
360	  const local = localRoot
361	    ? await scanPackDir(localPacksDir(localRoot), { local: true, subdir: LOCAL_PACKS_SUBDIR, checksFor }, errors)
362	    : [];
363	  // ASKED FOR, never assumed. A copied pack governs the SESSION - its prose, its skills,
364	  // its checks - and says nothing about the repository: a conformance sweep over the
365	  // shelf, a vendoring pass, a catalog generator would all read one person's pack as a
366	  // pack the repo carries. So the session-time readers opt in and everything else is
367	  // answered as if the directory were not there, which in their checkout it usually is not.
368	  //
369	  // Copied last, so a name already taken by the canon or by the repo's own packs keeps its
370	  // tracked owner: what a session copies extends the repository, exactly as a local pack
371	  // extends the canon, and may not silently replace either.
372	  const temp = session && localRoot
373	    ? await scanPackDir(tempPacksDir(localRoot), { temp: true, subdir: TEMP_PACKS_SUBDIR }, errors)
374	    : [];
375	  const byId = new Map();
376	  const packs = [];
377	  for (const pack of [...canon, ...local, ...temp]) {
378	    if (byId.has(pack.id)) {
379	      const first = byId.get(pack.id);
380	      const origin = (p) => (p.temp ? 'a copied pack' : p.local ? 'a local pack' : 'the canon');
381	      errors.push({
382	        what: `pack id "${pack.id}" is declared twice - by ${origin(first)} and ${origin(pack)}`,
383	        fix: pack.temp
384	          ? `rename the copied pack in ${TEMP_PACKS_SUBDIR}/ - it may not shadow a pack this repository tracks`
385	          : `rename the local pack in ${LOCAL_PACKS_SUBDIR}/ - a local pack id must be unique and may not shadow a canon pack`,
386	        dir: pack.dir,
387	      });
388	      continue;
389	    }
390	    byId.set(pack.id, pack);
391	    packs.push(pack);
392	  }
393	  return { packs, errors };
394	}
395	
396	// The pack list alone — the shape every non-runner caller wants. Canon-only when
397	// no localRoot is given (the fleet planner and the declaration-writing backfill
398	// run in the canon checkout and read member declarations over the API, not from
399	// local disk). A broken/duplicate pack is simply absent here; the runner's
400	// discoverPacks surfaces the diagnostic.
401	export async function loadPacks(opts) {
402	  return (await discoverPacks(opts)).packs;
403	}
404	
405	// A local pack's canonical declaration token is namespaced `local/<id>` —
406	// self-documenting in .claudinite-settings.json (a reader sees at a glance the
407	// pack lives in the repo's own tree under .claudinite/local/, and a canon id can
408	// never be claimed by accident; the discoverPacks shadow guard stays as the
409	// backstop). A bare id is still accepted - that is what a declaration written
410	// before the namespace existed says - so packEntryId strips the prefix where one is
411	// present and every id comparison happens on the bare id. The pre-rename
412	// `local_packs/<id>` form was read alongside it until #1640; a member still
413	// declaring it now activates nothing.
414	export const LOCAL_DECL_PREFIX = 'local/';
415	const stripLocalPrefix = (id) => (id.startsWith(LOCAL_DECL_PREFIX) ? id.slice(LOCAL_DECL_PREFIX.length) : id);
416	
417	// The writer-side inverse: the token a declaration writer records for a pack —
418	// namespaced (canonical form) for a local pack, the bare id for a canon one.
419	export const declTokenFor = (pack) =>
420	  pack.local ? LOCAL_DECL_PREFIX + pack.id : pack.id;
421	
422	// A `packs` declaration entry is either a plain id string or an entry object
423	// `{ id, config?, rules?, accept?, via? }` carrying that pack's own settings
424	// (see engine/checks/README.md). This is the one id-extractor every reader shares, so
425	// raw-JSON consumers (the SessionStart hooks, the fleet signal probe) and the
426	// engine agree on both shapes — and on both declaration forms: it returns the
427	// BARE pack id, stripping a `local/` namespace where one is declared.
428	// Returns undefined for a malformed entry.
429	// A declaration written before a canon pack was renamed resolves to the pack's
430	// CURRENT id here (renamed-packs.mjs), so activation, config lookup and the vendor
431	// set all agree on one spelling no matter which one the member wrote. A LOCAL pack
432	// is exempt: its namespace belongs to the repo, so `local/barriers` stays `barriers`.
433	// A local pack declared BARE cannot be told apart from a canon one at this seam and
434	// is canonicalized with the rest — which is harmless while the shadow guard in
435	// discoverPacks keeps a local id from claiming a canon one.
436	export const packEntryId = (entry) => {
437	  const raw = typeof entry === 'string'
438	    ? entry
439	    : entry !== null && typeof entry === 'object' && typeof entry.id === 'string'
440	      ? entry.id
441	      : undefined;
442	  if (raw === undefined) return undefined;
443	  const bare = stripLocalPrefix(raw);
444	  return bare === raw ? canonicalPackId(bare) : bare;
445	};
446	
447	// No TRACKED pack is active by default. Activation is exactly the project's declaration
448	// in .claudinite-settings.json (bootstrap's --init seeds the default-on packs).
449	//
450	// A COPIED pack is active by being there. Its directory was written this session, by a
451	// step the repo's declaration already activated, for the person the session belongs to -
452	// so the declaration that would govern it has been made, one level up, and repeating it
453	// per person in a shared file is the thing that shape exists to avoid.
454	export const isActive = (pack, config) =>
455	  pack.temp === true || (config.packs ?? []).some((entry) => packEntryId(entry) === pack.id);
456	
457	// The MOUNTED SKILL SET: the union of the given packs' bundled skills, as a
458	// Map(name -> the skill's directory). A bundled skill is `<pack>/skills/<name>/`
459	// carrying a SKILL.md — the one shape, canon and local alike (#385). The packs are
460	// taken in the caller's order and the FIRST occurrence of a name wins, so a caller
461	// passing canon packs before local ones resolves a shared name to canon.
462	//
463	// Read off each pack's own `skills`, which the convention fills from that same
464	// directory listing — so this is the tree's answer for every ordinary pack, and a
465	// manifest that withholds a name is honoured here rather than quietly re-derived.
466	//
467	// One definition, two readers: the SessionStart mount hook (mount-skills.mjs) turns
468	// it into `.claude/skills/` symlinks, and the usage fold asks it which skill names a
469	// typed `/command` could possibly be. The mounts themselves are gitignored session
470	// state, so anything reasoning about "what is mounted here" must ask the registry —
471	// this function — and never the mount directory.
472	export function bundledSkillSources(packs) {
473	  const byName = new Map();
474	  for (const pack of packs) {
475	    for (const name of pack.skills ?? []) {
476	      if (byName.has(name)) continue;
477	      const dir = join(pack.dir, 'skills', name);
478	      if (existsSync(join(dir, 'SKILL.md'))) byName.set(name, dir);
479	    }
480	  }
481	  return byName;
482	}
483	
484	// Import closure. A pack can't be imported without the packs it requires: a
485	// release pack builds on its coding pack, a project-class pack on the framework
486	// pack that implements it. A pack names those in its `requires` list.
487	// Given the entries a project declares (id strings or entry objects), return
488	// that set plus every pack reachable through `requires` (transitively).
489	// Declared entries keep their order; each pack's pulled-in dependencies land
490	// right after it, deterministically. This runs when the declaration is
491	// WRITTEN — bootstrap's `--init` and the update's backfill — so a pack's
492	// prerequisites are materialized into .claudinite-settings.json, visible and
493	// droppable like every other entry (the same reason a seeded pack is written
494	// explicitly rather than defaulted), never resolved implicitly at run time.
495	//
496	// Provenance: a materialized dependency is written as `{ id, via: [...] }`,
497	// `via` naming the resolved packs that directly require it — the file itself
498	// answers "why is this pack declared". An entry already carrying `via`
499	// self-identifies as materialized, so its `via` is recomputed to stay accurate
500	// as dependents come and go (an empty recomputed `via` marks an orphan the
501	// project can drop); a user-authored entry (no `via`) is kept verbatim.
502	// A declared id is kept verbatim even if unknown (settings validation flags
503	// that); a dependency is only materialized when it names a real pack; an
504	// entry with no usable id (a settings error) is preserved untouched — the
505	// writer must never drop what it can't interpret.
506	export function resolveDeclaredPacks(declared, packs) {
507	  const byId = new Map(packs.map((p) => [p.id, p]));
508	  const declaredIds = new Set(declared.map(packEntryId).filter((id) => id !== undefined));
509	  const entryById = new Map();
510	  for (const entry of declared) {
511	    const id = packEntryId(entry);
512	    if (id !== undefined && !entryById.has(id)) entryById.set(id, entry);
513	  }
514	  const orderedIds = [];
515	  const seen = new Set();
516	  const visit = (id) => {
517	    if (seen.has(id)) return;
518	    if (!declaredIds.has(id) && !byId.has(id)) return; // don't materialize a phantom dep
519	    seen.add(id);
520	    orderedIds.push(id);
521	    for (const dep of byId.get(id)?.requires ?? []) visit(dep);
522	  };
523	  for (const entry of declared) {
524	    const id = packEntryId(entry);
525	    if (id !== undefined) visit(id);
526	  }
527	  const via = (id) => orderedIds.filter((p) => byId.get(p)?.requires?.includes(id)).sort();
528	  const resolved = orderedIds.map((id) => {
529	    const entry = entryById.get(id);
530	    if (entry === undefined) return { id, via: via(id) };
531	    if (typeof entry === 'object' && 'via' in entry) return { ...entry, via: via(id) };
532	    return entry;
533	  });
534	  return [...resolved, ...declared.filter((entry) => packEntryId(entry) === undefined)];
535	}
