// A pack's fingerprint as data: which tracked paths suggest the pack, and optionally
// what one of those files must contain. Because it is data rather than a function,
// every reader evaluates the same spec its own way: a session over its checkout, the
// fleet sweep over a member's tree listing, a dashboard in a browser over GitHub's API,
// which can narrow the text half with a code search for the `search` terms before
// reading anything. A relevance detector only suspects a pack is wanted; declaring it is the
// project's call.
//
//   about   what a person reads: the thing found, in words
//   paths   a RegExp tested against each tracked path
//   text    optional RegExp, or list of them, every one matching the same file
//   search  code-search terms, required with `text`: a file `text` matches contains
//           at least one of them, so a search for any of them finds every candidate
//
// No filesystem and no imports, so a browser can load it as it is.

// GitHub's code search refuses a query with more than five AND/OR/NOT operators, and
// the terms are joined with OR into one query.
export const MAX_SEARCH_TERMS = 6;

const KEYS = new Set(['about', 'paths', 'text', 'search']);
const isPattern = (v) => v instanceof RegExp;
const patterns = (text) => (text === undefined ? [] : [].concat(text));

// A `g` or `y` pattern keeps state between `.test` calls, so the second file tested
// could fail on what the first left behind.
const stateless = (r) => !/[gy]/.test(r.flags);

export function validateRelevanceDetector(relevanceDetector) {
  if (relevanceDetector === null) return [];
  if (typeof relevanceDetector !== 'object' || Array.isArray(relevanceDetector)) return ['relevanceDetector is an object or null'];
  const errors = [];
  for (const key of Object.keys(relevanceDetector)) if (!KEYS.has(key)) errors.push(`relevanceDetector declares "${key}", which is not one of ${[...KEYS].join(', ')}`);
  if (typeof relevanceDetector.about !== 'string' || !relevanceDetector.about.trim()) errors.push('relevanceDetector.about names what is found, in words');
  if (!isPattern(relevanceDetector.paths)) errors.push('relevanceDetector.paths is a RegExp over tracked paths');
  const text = patterns(relevanceDetector.text);
  if (!text.every(isPattern)) errors.push('relevanceDetector.text is a RegExp or a list of them');
  const all = [relevanceDetector.paths, ...text].filter(isPattern);
  if (!all.every(stateless)) errors.push('a relevanceDetector pattern carries the g or y flag, which makes .test stateful');
  if (text.length && !(Array.isArray(relevanceDetector.search) && relevanceDetector.search.length && relevanceDetector.search.every((s) => typeof s === 'string' && s.trim()))) {
    errors.push('relevanceDetector.search lists the code-search terms that find every file relevanceDetector.text matches');
  }
  if (Array.isArray(relevanceDetector.search) && relevanceDetector.search.length > MAX_SEARCH_TERMS) {
    errors.push(`relevanceDetector.search names ${relevanceDetector.search.length} terms; one code search joins at most six`);
  }
  return errors;
}

export const detectorCandidates = (relevanceDetector, tracked) => tracked.filter((f) => relevanceDetector.paths.test(f));

export function detectsRelevance(relevanceDetector, ctx) {
  if (!relevanceDetector) return false;
  const text = patterns(relevanceDetector.text);
  return ctx.tracked.some((f) => {
    if (!relevanceDetector.paths.test(f)) return false;
    if (!text.length) return true;
    const body = ctx.read(f);
    return body !== null && text.every((r) => r.test(body));
  });
}

const patternData = (r) => ({ source: r.source, flags: r.flags });

// The spec with every pattern as { source, flags }: what a reader outside this
// runtime, or across a JSON boundary, rebuilds with `new RegExp(source, flags)`.
export function relevanceDetectorData(relevanceDetector) {
  if (!relevanceDetector) return null;
  return {
    about: relevanceDetector.about,
    paths: patternData(relevanceDetector.paths),
    ...(relevanceDetector.text !== undefined ? { text: patterns(relevanceDetector.text).map(patternData) } : {}),
    ...(relevanceDetector.search ? { search: [...relevanceDetector.search] } : {}),
  };
}
#!/usr/bin/env node
// Environment requirements — a pack declares a toolchain (or per-repo deps) a
// cloud session needs but the base image doesn't ship, via an optional `env`
// field on its pack.mjs. Driven by the repo's ACTIVE packs and the per-pack
// parameters it supplies in .claudinite-settings.json (each pack entry's
// `config`, which loadConfig presents as the `packConfig` view):
//
//   node env.mjs install   Run every active pack's `setup` in the checkout. The
//                          one generic environment-setup script — the web pack's,
//                          pasted into the environment's Setup script field —
//                          calls this; installs land in the environment image
//                          (snapshotted, reused).
//   node env.mjs check     SessionStart assertion (web only): run every active
//                          pack's `probe`; if a requirement isn't actually
//                          present, inject the halt-gate context telling the
//                          assistant to have the user re-run the setup. A pure
//                          assertion on the real environment — no version flag;
//                          the probes ARE the source of truth.
//   node env.mjs plan      Print what install would run (review / debug).
//
// A pack's declaration — `setup` and `probe` may be a string, or a function of
// the project's per-pack params (so a repo can say WHERE its package.json is):
//   env: {
//     label: 'Node dependencies',
//     setup: (p) => (p.dirs ?? ['.']).map((d) => `( cd "${d}" && npm ci ) || true`).join('\n'),
//     probe: (p) => (p.dirs ?? ['.']).map((d) => `[ -d "${d}/node_modules" ]`).join(' && '),
//   }
import { pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';
import { loadPacks, isActive } from './pack-registry.mjs';
import { loadConfig } from '../checks/helpers/repo-context.mjs';

const resolveField = (field, params) =>
  typeof field === 'function' ? field(params) : field;

/**
 * The env declarations of a repo's active packs, each resolved against the
 * project's per-pack params (each pack entry's `config` in
 * .claudinite-settings.json, via loadConfig's normalized packConfig view).
 */
export async function activeEnvs(projectRoot, { packs, config } = {}) {
  config ??= loadConfig(projectRoot);
  // Include the project's own local packs — a local pack may declare an `env`
  // toolchain requirement just like a canon pack.
  packs ??= await loadPacks({ localRoot: projectRoot });
  return packs
    .filter((p) => p.env && isActive(p, config))
    .map((p) => {
      const params = (config.packConfig && config.packConfig[p.id]) || {};
      return {
        id: p.id,
        label: p.env.label ?? p.id,
        setup: resolveField(p.env.setup, params),
        probe: resolveField(p.env.probe, params),
      };
    });
}

/** Pure decision: which active requirements aren't present. `probe(env) -> bool`. */
export function evaluate(envs, probe) {
// THE PACK MANIFEST SPEC — the single declarative statement of what a
// `pack.mjs` may and must carry. Everything a pack declares about itself is
// described here once, and `validateManifest` is the only thing that judges a
// manifest against it. The loader calls it on every pack it imports (canon and a
// consumer's own `local/packs/` alike), so a malformed or incomplete manifest
// surfaces as a blocking `config` error at load — the same class as invalid JSON
// in `.claudinite-settings.json`.
//
// WHY A SPEC AND NOT A CHECK. A required manifest field is part of the pack
// contract, not a conformance opinion about a repo's content: a conformance rule
// would have to be declared BY a pack, run only when that pack is active, and
// re-derive the manifest by reading its source text — enforcing the shape of the
// system from inside one of its members. The spec is upstream of every pack, so
// there is nothing to declare and nothing to parse.
//
// No filesystem, and its one import is the engine's own pure version module: the
// caller supplies the facts from disk (the `skills/` directory listing), so this
// module is pure and testable standalone. Its other half is
// `pack-conventions.mjs`, which reads the pack directory and fills in what the
// tree already says — so by the time a manifest reaches this spec, `id`, `prose`,
// `badge` and `skills` are present whether or not the author wrote them.
import { isDeclaredVersion } from '../version.mjs';
import { validateRelevanceDetector } from './relevance-detector.mjs';

// The routing budget. Both sides of `ruleRoutingGuidance` become one row of the
// pack catalog (packs/directory.GENERATED.md), which a session reads when deciding
// which pack owns a piece of content — so the cap keeps a row scannable: enough for
// a boundary and a pointer to the pack that owns the other side.
export const MAX_ROUTING_WORDS = 20;

// The pitch budget. A pitch is the paragraph a repo that does not run Claudinite reads
// when a dashboard says the pack would fit it: one paragraph, so it stays read.
export const MAX_PITCH_WORDS = 100;

// The two conformance scopes. A rule's scope is its PLACEMENT on the manifest —
// `worldRules` audit repo state, `workRules` judge the change and session in
// front of you — so the two runners' partition is declared where a reader of the
// pack can see it, and a rule module never restates (or contradicts) it.
export const RULE_SCOPES = { worldRules: 'world', workRules: 'work' };
// The work list also homes a declaration judging a TOOL CALL (`scope: 'action'`
// — engine/checks/helpers/pattern-rules.mjs): it runs at Stop like a work rule
// and at PreToolUse besides, and keeps that finer scope through normalization.
export const WORK_LIST_SCOPES = new Set(['work', 'action']);

// disk). Returns `{ what, fix }` errors — the loader's error shape — never
// throws, so one bad manifest can't sink the run.
export function validateManifest(mod, { label, skillDirs = [] } = {}) {
  const errors = [];
  const at = label ? `${label}: ` : '';
  const err = (what, fix) => errors.push({ what: `${at}${what}`, fix });

  if (!isPlainObject(mod)) {
    err('the pack has no object default export', 'export default { version, ruleRoutingGuidance, ... } from its pack.mjs');
    return errors;
  }

  for (const key of REQUIRED) {
    if (!(key in mod)) err(`declares no "${key}"`, `add "${key}" — ${PACK_FIELDS[key].describe}`);
  }
  for (const [key, value] of Object.entries(mod)) {
    const field = PACK_FIELDS[key];
    if (!field) {
      err(`declares "${key}", which is not a pack manifest field`, `remove it, or add it to the spec in engine/pack_loader/pack-schema.mjs — the known fields are: ${Object.keys(PACK_FIELDS).join(', ')}`);
      continue;
    }
    if (!field.valid(value)) err(`"${key}" is not a valid value`, `${key} is ${field.describe}`);
  }

  if (isPlainObject(mod.ruleRoutingGuidance)) {
    for (const side of ['belongs', 'excludes']) {
      const v = mod.ruleRoutingGuidance[side];
      if (typeof v !== 'string' || !v.trim()) {
        err(`ruleRoutingGuidance declares no "${side}"`, side === 'belongs'
          ? 'state the kind of content this pack owns, in at most 20 words'
          : 'state what belongs elsewhere and which pack owns it, in at most 20 words');
        continue;
      }
      const n = wordCount(v);
      if (n > MAX_ROUTING_WORDS) {
        err(`ruleRoutingGuidance.${side} is ${n} words, over the ${MAX_ROUTING_WORDS}-word cap`,
          `cut it to ${MAX_ROUTING_WORDS} words — it is one row of a table every session loads`);
      }
    }
  }

  if (typeof mod.pitch === 'string' && wordCount(mod.pitch) > MAX_PITCH_WORDS) {
    err(`pitch is ${wordCount(mod.pitch)} words, over the ${MAX_PITCH_WORDS}-word cap`, `cut it to ${MAX_PITCH_WORDS} words, since it is one paragraph a newcomer reads`);
  }

  if ('relevanceDetector' in mod) for (const what of validateRelevanceDetector(mod.relevanceDetector ?? null)) err(what, 'see engine/pack_loader/relevance-detector.mjs for the shape');

  // A rule's scope is where it is declared; the manifest is the authority. A
  // rule module may still carry `scope` for the dispatch seam that reads it off
  // the rule object (engine/checks/helpers/work.mjs — which hands a work rule
  // its fluent surface), but then the two must AGREE: a module that says one
  // thing while the list it sits in says another is drift with a wrong context
  // waiting at the end of it.
  for (const [key, scope] of Object.entries(RULE_SCOPES)) {
    if (!isRuleArray(mod[key])) continue;
    for (const rule of mod[key]) {
      if ('scope' in rule && rule.scope !== scope && !(key === 'workRules' && WORK_LIST_SCOPES.has(rule.scope))) {
        err(`the rule "${rule.id}" declares scope "${rule.scope}" but sits in ${key}`,
          `move the rule to the list matching its scope, or drop its "scope" field — the manifest decides`);
      }
    }
  }

  // A declared skill name with no directory behind it is a manifest that lies —
  // the mount would announce a skill no session can load. The other direction is
  // not a fault any more: the convention lists every `skills/<name>/` carrying a
  // SKILL.md, so a name missing from the list is there because the manifest
  // deliberately overrode it, which is what withholding a skill looks like.
  if (isStringArray(mod.skills)) {
    for (const name of mod.skills) {
