// The record declares `updateTaskSchedulingFields: true`; the rewrite ships with the
// engine (task-declarations-to-json.mjs) and is the same one the CLI runs.
//
// Needs the directory listing beyond the classic io; a caller without it rewrites
// nothing rather than half-rewriting, and both retired shapes keep working at the
// door until a worker that can do the step runs.
export async function applyTaskSchedulingFields(migration, io) {
  if (!migration.updateTaskSchedulingFields) return [];
  if (typeof io.listDir !== 'function') return [];
  if (migration.appliesTo && !(await migration.appliesTo(io.read))) return [];
  return updateTaskSchedulingFields(taskDirsWithJson([LOCAL_PACK_ROOT], io), io);
}

// Write side - "this repo's local packs carry their provenance" (docs/provenance/DESIGN.md
// §6): every local pack's `references.md` converts into entries on the elements it keyed,
// every rule and guideline ends with a marker, every skill declares its body, every
// carrier has its file. A NAMED CODEMOD like the two above it - the record declares
// `markProvenance: true`, and the code ships with the engine
// (engine/checks/helpers/provenance.mjs, the grammar every reader of a provenance folder
// composes) - because which rules are unmarked and which skills are workflows is the
// repo's own disk. Idempotent: a pack already on the convention is left as it is.
//
// Dates an entry by the conversion, not by git: the registry's io reads files, not
// history, and the entry's title says so. Needs `listDir` like the task-fields op; a
// caller without it marks nothing rather than half-marking, and `remove` for the doc it
// retires - an io without that leaves the doc and reports it.
export async function applyProvenanceMarking(migration, io) {
  if (!migration.markProvenance) return [];
  if (typeof io.listDir !== 'function') return [];
  if (migration.appliesTo && !(await migration.appliesTo(io.read))) return [];
  const applied = [];
  for (const pack of (io.listDir(LOCAL_PACK_ROOT) ?? []).sort()) {
    const dir = `${LOCAL_PACK_ROOT}/${pack}`;
    if (!io.exists(`${dir}/pack.mjs`)) continue;
    applied.push(...convertReferences(dir, io));
    applied.push(...markPack(dir, io));
  }
  return applied;
}

// Write side - "a check says what it does when it fails": `severity: "blocking" |
// "advisory"` becomes `on_fail: "block" | "advise"` in the member's own files - its
// settings overrides, its local packs' declared checks, and the rule objects and
// `finding()` calls in its local packs' check modules. A NAMED CODEMOD like the ones
// above: which files carry the field is the repo's own disk, so it needs `listDir`,
// and a caller without it rewrites nothing rather than half-rewriting. A pack's
// `test/` is the member's own assertions and is left alone; the engine mirrors the
// old field on every finding while the old spelling is read at all.
const ON_FAIL_OF = { blocking: 'block', advisory: 'advise' };
const OLD_DECLARED = /"severity"(\s*:\s*)"(blocking|advisory)"/g;
const OLD_CODED = /\bseverity(\s*:\s*)(['"])(blocking|advisory)\2/g;

function localCheckFiles(io) {
  const out = [];
  const walk = (dir) => {
    for (const name of (io.listDir(dir) ?? []).sort()) {
      const path = `${dir}/${name}`;
      if (name === 'declared-checks.json' || (name.endsWith('.mjs') && !name.endsWith('.test.mjs'))) out.push(path);
      else if (name !== 'test' && name !== 'node_modules' && !name.includes('.')) walk(path);
