import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { relevanceDetectorFromData } from './relevance-detector.mjs';

// A PACK'S MANIFEST FILE. `pack.json` is the manifest as data; `pack.mjs`, a module
// default-exporting the same object, is the older spelling and is still read. A
// directory carrying either is a pack, and where it carries both the JSON wins, so a
// conversion never has to delete in the same step it writes.
//
// Everything that has to find, read or name a manifest asks this module: the loader,
// the version readers that scrape a manifest's text over the API, the checks that
// select manifests by path.
export const MANIFEST_JSON = 'pack.json';
export const MANIFEST_MODULE = 'pack.mjs';
export const MANIFEST_FILES = [MANIFEST_JSON, MANIFEST_MODULE];

// A manifest's path, either spelling: `<anything>/pack.json` or `<anything>/pack.mjs`.
export const isManifestPath = (path) => /(?:^|\/)pack\.(?:json|mjs)$/.test(path);

// The manifest a pack directory carries, preferred spelling first, or null. `exists`
// answers for a file name inside that directory, so a caller holding a tree listing,
// a git ref or the disk asks the same question.
export const manifestFileIn = (exists) => MANIFEST_FILES.find((name) => exists(name)) ?? null;

// The fields a manifest may hold that JSON cannot spell natively, rebuilt: each
// `relevanceDetector` pattern written as a string or as `{ source, flags }`. A module
// manifest may already carry RegExp objects, which pass through untouched. A pattern
// that does not compile throws, and the loader reports it as the pack failing to load.
export function hydrateManifest(mod) {
  if (mod === null || typeof mod !== 'object' || Array.isArray(mod)) return mod;
  if (!mod.relevanceDetector) return mod;
  return { ...mod, relevanceDetector: relevanceDetectorFromData(mod.relevanceDetector) };
}

// Read one manifest file into the object the loader merges its conventions into.
export async function readManifest(file) {
  const raw = file.endsWith('.json')
    ? JSON.parse(readFileSync(file, 'utf8'))
    : (await import(pathToFileURL(file).href)).default;
  return hydrateManifest(raw);
}

