p='engine/pack_loader/pack-conventions.mjs'
s=open(p).read()
old="""export const PROSE_FILE = 'RULES.md';"""
new="""export const PROSE_FILE = 'RULES.md';
// The manifest: `pack.json` is data, and `pack.mjs`, a module default-exporting the same
// object, is the older spelling and still read. A directory carrying either is a pack;
// carrying both, the JSON wins. Every reader that finds or names a manifest asks here.
export const MANIFEST_JSON = 'pack.json';
export const MANIFEST_MODULE = 'pack.mjs';
export const MANIFEST_FILES = [MANIFEST_JSON, MANIFEST_MODULE];
// The manifest a pack directory carries, preferred spelling first, or null. `exists`
// answers for a file name inside that directory, so a caller holding a tree listing, a
// git ref or the disk asks the same question.
export const manifestFileIn = (exists) => MANIFEST_FILES.find((name) => exists(name)) ?? null;"""
assert s.count(old)==1; s=s.replace(old,new); open(p,'w').write(s)
EOF
cat > engine/pack_loader/pack-manifest.mjs <<'EOF'
import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { relevanceDetectorFromData } from './relevance-detector.mjs';

// READING A PACK'S MANIFEST, either spelling (pack-conventions.mjs names them). A
// module manifest is imported; a JSON one is parsed, and the fields JSON cannot spell
// natively are rebuilt: each `relevanceDetector` pattern, written as a string or as
// `{ source, flags }`. A module manifest may already carry RegExp objects, which pass
// through untouched. A pattern that does not compile throws, and the loader reports it
// as the pack failing to load.
export function hydrateManifest(mod) {
  if (mod === null || typeof mod !== 'object' || Array.isArray(mod)) return mod;
  if (!mod.relevanceDetector) return mod;
  return { ...mod, relevanceDetector: relevanceDetectorFromData(mod.relevanceDetector) };
}

export async function readManifest(file) {
  const raw = file.endsWith('.json')
    ? JSON.parse(readFileSync(file, 'utf8'))
    : (await import(pathToFileURL(file).href)).default;
  return hydrateManifest(raw);
}
EOF
grep -rln "pack-manifest.mjs" --include=*.mjs . | grep -v node_modules | grep -v "^./.claudinite/shared"

