import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { makeRepo, cleanup, writeFiles, declaredCheck } from '../../../engine-tests/helpers.mjs';
import { buildContext } from '../../../engine/checks/helpers/repo-context.mjs';
import pack from '../pack.mjs';
import { skillMetadata } from '../../../engine/pack_loader/skill-frontmatter.mjs';

const layout = declaredCheck('packs/product-wiki', 'product-wiki-layout');
const pageSections = declaredCheck('packs/product-wiki', 'product-wiki-page-sections');
const keyInsights = declaredCheck('packs/product-wiki', 'product-wiki-key-insights');
const growthLog = declaredCheck('packs/product-wiki', 'product-wiki-growth-log');
const sources = declaredCheck('packs/product-wiki', 'product-wiki-sources');
const freshness = declaredCheck('packs/product-wiki', 'product-wiki-freshness');
import wikiGrowthJson from '../tasks/wiki-growth/task.json' with { type: 'json' };
import { normalizeTaskDeclaration } from '../../claudinite-tasks/public/task-declaration.mjs';
import * as detectorSpec from '../../../engine/pack_loader/relevance-detector.mjs';

// --- pack manifest -----------------------------------------------------------

test('the writing-wiki-pages skill scopes itself to the tree, and the weekly worker loads it by name', () => {
  // Two artifacts that could drift: the skill's own force-load scope, and the task
  // doc that names it.
  assert.ok(skillMetadata(join(here, '..', 'skills', 'writing-wiki-pages')).forceLoadPaths.length, 'the skill forces itself for files');
  assert.ok(readFileSync(join(here, '..', 'tasks', 'wiki-growth', 'task.md'), 'utf8').includes('skill: `writing-wiki-pages`'));
});

test('detect fires exactly on the sink marker', () => {
  assert.equal(detectorSpec.detectsRelevance(pack.relevanceDetector, { tracked: ['product-wiki/product-requirements/README.md'], read: () => null }), true);
  assert.equal(detectorSpec.detectsRelevance(pack.relevanceDetector, { tracked: ['product-wiki/Market/README.md'], read: () => null }), false);
});

// --- product-wiki-layout ------------------------------------------------------
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { cleanup, makeRepo } from '../../../engine-tests/helpers.mjs';
import { buildContext } from '../../../engine/checks/helpers/repo-context.mjs';
import pack from '../pack.mjs';
import * as detectorSpec from '../../../engine/pack_loader/relevance-detector.mjs';

const detect = (root) => detectorSpec.detectsRelevance(pack.relevanceDetector, buildContext({ root, mode: 'all' }));

test('the pack fingerprints a repo whose page carries the version stamp', () => {
  const root = makeRepo({ base: {
    'package.json': '{ "version": "1.10913.4" }\n',
    'site/index.html': '<p title="version 1.10913.4">c</p>\n',
  } });
  try { assert.equal(detect(root), true); } finally { cleanup(root); }
});

// A version record alone is every node project; a page with an unrelated title is
// every site. Neither says "public website" on its own.
test('the pack is inert on a repo with no stamped page (FP guard)', () => {
  const root = makeRepo({ base: {
    'package.json': '{ "version": "1.2.3" }\n',
    'index.html': '<p title="about us">c</p>\n',
  } });
  try { assert.equal(detect(root), false); } finally { cleanup(root); }
});

// The pack composes with a hosting pack by that pack reaching its public seam — never
// the other way round — so nothing in the manifest may name one.
test('the manifest names no hosting pack', () => {
  const text = JSON.stringify(pack.ruleRoutingGuidance) + (pack.requires ?? []).join(' ');
  assert.doesNotMatch(text, /github-pages|cloudflare|pages\b/i);
});

