    if (!d || pack.manifestFile !== 'pack.mjs') continue;
    const file = join(pack.dir, 'pack.mjs');
    let text = readFileSync(file, 'utf8');
    for (const re of [d.paths, ...[].concat(d.text ?? [])]) {
      if (!(re instanceof RegExp)) continue;
      const lit = String(re);
      if (text.split(lit).length !== 2) throw new Error(`${file}: ${lit} is not written exactly once`);
      text = text.replace(lit, () => literal(re));
    }
    writeFileSync(file, text);
    console.log(`rewrote ${file}`);
  }
}

