// Rewrite every RegExp literal a canon pack.mjs's relevanceDetector holds as its JSON
// form (a source string, or { source, flags }), then prove the loaded detector unchanged.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const root = process.argv[2];
const { loadPacks } = await import(pathToFileURL(join(root, 'engine/pack_loader/pack-registry.mjs')).href);
const spec = (d) => d && JSON.stringify({ ...d, paths: [d.paths.source, d.paths.flags], text: [].concat(d.text ?? []).map((r) => [r.source, r.flags]) });
const before = new Map((await loadPacks()).map((p) => [p.id, spec(p.relevanceDetector)]));

const literal = (re) => {
  const source = JSON.stringify(re.source.replace(/\\\//g, '/'));
  return re.flags ? `{ source: ${source}, flags: '${re.flags}' }` : source;
};
let rewritten = 0;
for (const pack of await loadPacks()) {
  const d = pack.relevanceDetector;
  if (!d || pack.manifestFile !== 'pack.mjs') continue;
  const file = join(pack.dir, 'pack.mjs');
  let text = readFileSync(file, 'utf8');
  for (const re of [d.paths, ...[].concat(d.text ?? [])]) {
    const lit = String(re);
    if (text.split(lit).length !== 2) throw new Error(`${file}: ${lit} is not written exactly once`);
    text = text.replace(lit, () => literal(re));
  }
  writeFileSync(file, text);
  rewritten += 1;
}
const after = new Map((await import(`${pathToFileURL(join(root, 'engine/pack_loader/pack-registry.mjs')).href}?after`)).loadPacks
  ? (await (await import(`${pathToFileURL(join(root, 'engine/pack_loader/pack-registry.mjs')).href}?after`)).loadPacks()).map((p) => [p.id, spec(p.relevanceDetector)])
  : []);
console.log(`rewrote ${rewritten} manifests`);
process.stdout.write(`${JSON.stringify({ before: [...before], after: [...after] })}\n`);

