// Strip every comment from each pack.mjs named on argv, string-aware, dropping the lines
// that held only a comment and the blank lines the removal leaves inside the manifest.
import { readFileSync, writeFileSync } from 'node:fs';
import { stripComments } from '/home/user/Claudinite/engine/checks/helpers/code-scanning.mjs';

for (const file of process.argv.slice(2)) {
  const source = readFileSync(file, 'utf8');
  const stripped = stripComments(source);
  const a = source.split('\n');
  const b = stripped.split('\n');
  if (a.length !== b.length) throw new Error(`${file}: stripping moved lines`);
  const out = [];
  for (let i = 0; i < a.length; i += 1) {
    const had = a[i].trim() !== '';
    const kept = b[i].replace(/\s+$/, '');
    if (had && kept.trim() === '') continue; // a comment-only line
    out.push(kept);
  }
  // No blank line at the top, none inside the object, one before `export default` if imports precede it.
  let text = out.join('\n').replace(/^\n+/, '');
  text = text.replace(/\{\n(\s*\n)+/g, '{\n').replace(/\n(\s*\n)+(\s*[}\]])/g, '\n$2');
  text = text.replace(/(export default \{[\s\S]*)$/, (m) => m.replace(/,\n\s*\n/g, ',\n'));
  if (text !== source) { writeFileSync(file, text); console.log(`stripped ${file}`); }
}

