1	import { readFileSync } from 'node:fs';
2	import { pathToFileURL } from 'node:url';
3	import { relevanceDetectorFromData } from './relevance-detector.mjs';
4	
5	// READING A PACK'S MANIFEST, either spelling (pack-conventions.mjs names them). A
6	// module manifest is imported; a JSON one is parsed, and the fields JSON cannot spell
7	// natively are rebuilt: each `relevanceDetector` pattern, written as a string or as
8	// `{ source, flags }`. A module manifest may already carry RegExp objects, which pass
9	// through untouched. A pattern that does not compile throws, and the loader reports it
10	// as the pack failing to load.
11	export function hydrateManifest(mod) {
12	  if (mod === null || typeof mod !== 'object' || Array.isArray(mod)) return mod;
13	  if (!mod.relevanceDetector) return mod;
14	  return { ...mod, relevanceDetector: relevanceDetectorFromData(mod.relevanceDetector) };
15	}
16	
17	export async function readManifest(file) {
18	  const raw = file.endsWith('.json')
19	    ? JSON.parse(readFileSync(file, 'utf8'))
20	    : (await import(pathToFileURL(file).href)).default;
21	  return hydrateManifest(raw);
22	}

